const products = [
  {id:1,name:'Noise Heavyweight Tee',category:'apparel',type:'Apparel / Black',price:389000,image:'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?auto=format&fit=crop&w=900&q=85',tag:'Best seller'},
  {id:2,name:'Goddess Club Vinyl',category:'music',type:'Music / Limited pressing',price:649000,image:'https://images.unsplash.com/photo-1539375665275-f9de415ef9ac?auto=format&fit=crop&w=900&q=85',tag:'Limited'},
  {id:3,name:'After Hours Hoodie',category:'apparel',type:'Apparel / Washed black',price:729000,image:'https://images.unsplash.com/photo-1556821840-3a63f95609a7?auto=format&fit=crop&w=900&q=85',tag:''},
  {id:4,name:'Club Logo Pin Set',category:'objects',type:'Objects / 3 piece set',price:189000,image:'https://images.unsplash.com/photo-1601814933824-fd0b574dd592?auto=format&fit=crop&w=900&q=85',tag:'New'},
  {id:5,name:'Live Archives CD',category:'music',type:'Music / Digipak',price:249000,image:'https://images.unsplash.com/photo-1619983081563-430f63602796?auto=format&fit=crop&w=900&q=85',tag:''},
  {id:6,name:'First Press Boxset',category:'objects',type:'Objects / Collector edition',price:1199000,image:'https://images.unsplash.com/photo-1577083288073-40892c0860a4?auto=format&fit=crop&w=900&q=85',tag:'Only 12 left'}
];
let cart = JSON.parse(localStorage.getItem('goddess-cart') || '[]');
const money = value => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value).replace('Rp','Rp ');
const grid = document.querySelector('#product-grid');
function renderProducts(){const category=document.querySelector('.category-tabs button.active').dataset.category;const query=document.querySelector('#search-input').value.toLowerCase();const visible=products.filter(p=>(category==='all'||p.category===category)&&`${p.name} ${p.type}`.toLowerCase().includes(query));grid.innerHTML=visible.length?visible.map((p,i)=>`<article class="product-card" style="animation-delay:${i*60}ms"><div class="product-image"><img src="${p.image}" alt="${p.name}" loading="lazy">${p.tag?`<span class="product-tag">${p.tag}</span>`:''}<button class="quick-add" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div><div class="product-info"><div><h3>${p.name}</h3><p>${p.type}</p></div><span class="product-price">${money(p.price)}</span></div></article>`).join(''):'<p class="empty-state">No pieces found in the archive.</p>';}
function renderCart(){const count=cart.reduce((sum,item)=>sum+item.quantity,0);const total=cart.reduce((sum,item)=>sum+item.price*item.quantity,0);document.querySelector('#cart-count').textContent=count;document.querySelector('#bag-title').textContent=`${count} item${count===1?'':'s'}`;document.querySelector('#cart-total').textContent=money(total);const checkout=document.querySelector('#checkout-button');checkout.disabled=!cart.length;document.querySelector('#cart-items').innerHTML=cart.length?cart.map(item=>`<div class="cart-row"><img src="${item.image}" alt="${item.name}"><div><h3>${item.name}</h3><p>${money(item.price)}</p><div class="quantity"><button data-quantity="${item.id}" data-change="-1">-</button><span>${item.quantity}</span><button data-quantity="${item.id}" data-change="1">+</button></div></div><strong class="product-price">${money(item.price*item.quantity)}</strong></div>`).join(''):'<p class="empty-state">Your bag is waiting for something good.</p>';localStorage.setItem('goddess-cart',JSON.stringify(cart));}
function openCart(){document.querySelector('#overlay').hidden=false;document.querySelector('#cart-drawer').classList.add('open');document.querySelector('#cart-drawer').setAttribute('aria-hidden','false');}
function closePanels(){document.querySelector('#overlay').hidden=true;document.querySelector('#cart-drawer').classList.remove('open');document.querySelector('#cart-drawer').setAttribute('aria-hidden','true');document.querySelector('#checkout-modal').hidden=true;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200);}
document.addEventListener('click',event=>{const add=event.target.closest('[data-add]');if(add){const product=products.find(p=>p.id===Number(add.dataset.add));const existing=cart.find(item=>item.id===product.id);existing?existing.quantity++:cart.push({...product,quantity:1});renderCart();toast(`${product.name} added to your bag`);}const quantity=event.target.closest('[data-quantity]');if(quantity){const item=cart.find(p=>p.id===Number(quantity.dataset.quantity));item.quantity+=Number(quantity.dataset.change);if(item.quantity<1)cart=cart.filter(p=>p.id!==item.id);renderCart();}const tab=event.target.closest('[data-category]');if(tab){document.querySelectorAll('[data-category]').forEach(button=>button.classList.remove('active'));tab.classList.add('active');renderProducts();}if(event.target.matches('[data-close]'))closePanels();});
document.querySelector('#search-input').addEventListener('input',renderProducts);document.querySelector('#cart-button').addEventListener('click',openCart);document.querySelector('#overlay').addEventListener('click',closePanels);document.querySelector('#checkout-button').addEventListener('click',()=>{document.querySelector('#checkout-modal').hidden=false;});document.querySelector('#checkout-form').addEventListener('submit',event=>{event.preventDefault();cart=[];renderCart();closePanels();toast('Order received. DOKU payment link is ready.');});document.querySelector('#account-button').addEventListener('click',()=>toast('Account login is coming with the Laravel backend.'));document.querySelector('#search-toggle').addEventListener('click',()=>document.querySelector('#search-input').focus());renderProducts();renderCart();